      "A Lei de Drogas trata de forma bastante diferente o usuário e o traficante — e essa distinção é um dos pontos mais cobrados em prova de segurança pública, porque é justamente a abordagem policial que precisa fazer essa avaliação inicial no momento do flagrante. Quem adquire, guarda, tem em depósito, transporta ou traz consigo droga para consumo pessoal não recebe pena privativa de liberdade: as penas são advertência sobre os efeitos das drogas, prestação de serviços à comunidade e medida educativa de comparecimento a programa/curso.",
      "Para diferenciar consumo pessoal de tráfico, o art. 28, §2º, estabelece critérios objetivos e subjetivos que o juiz (e, na prática, primeiro o policial e o delegado) deve considerar em conjunto: natureza e quantidade da substância apreendida, o local e as condições em que se desenvolveu a ação, as circunstâncias sociais e pessoais do agente, bem como sua conduta e antecedentes. Não existe uma quantidade fixa em lei que separe automaticamente uso de tráfico — é uma análise do conjunto de circunstâncias.",
      "Tráfico de drogas (art. 33) é crime equiparado a hediondo, com pena de reclusão de 5 a 15 anos e multa — abrange condutas como importar, exportar, vender, expor à venda, oferecer, ter em depósito, transportar, trazer consigo, entre outras, com finalidade de comércio ou distribuição. O tráfico privilegiado (art. 33, §4º) permite redução de pena de um sexto a dois terços quando o agente é primário, de bons antecedentes, não se dedica a atividades criminosas nem integra organização criminosa."
