        "respostaEsperada": "Imagine como aprender as regras de um jogo sério: primeiro você entende quem pode agir, quando pode agir e qual consequência acontece. Neste capítulo, \"Lei de Drogas (Lei 11.343/2006): tráfico x uso pessoal\", a ideia principal é: A Lei de Drogas trata de forma bastante diferente o usuário e o traficante — e essa distinção é um dos pontos mais cobrados em prova de segurança pública, porque é justamente a abordagem policial que precisa fazer essa avaliação inicial no momento do flagrante. Para estudar sem travar, guarde primeiro estas palavras-chave: uso pessoal, tráfico de drogas, natureza e quantidade. Depois responda: o que a banca quer que eu reconheça? A frase de memória é: Não existe quantidade fixa que separe uso de tráfico — a lei manda avaliar o conjunto: natureza, quantidade, local, instrumentos e perfil do agente.",
