    "corpo": [
      "A Lei Maria da Penha cria mecanismos para coibir a violência doméstica e familiar contra a mulher, configurada por qualquer ação ou omissão baseada no gênero que cause morte, lesão, sofrimento físico, sexual ou psicológico, dano moral ou patrimonial. A lei reconhece cinco formas de violência: física, psicológica, sexual, patrimonial e moral — cada uma com definição própria no texto legal, não se restringindo a agressões físicas.",
      "O âmbito de aplicação da lei abrange três contextos: unidade doméstica (espaço de convívio permanente de pessoas, com ou sem vínculo familiar, incluindo agregados), família (comunidade formada por indivíduos unidos por laços naturais, afinidade ou vontade expressa) e relação íntima de afeto (na qual o agressor conviva ou tenha convivido com a ofendida, independentemente de coabitação) — o STJ já pacificou que a lei se aplica também a relações homoafetivas entre mulheres.",
      "A vítima pode requerer diretamente à autoridade policial ou ao juiz medidas protetivas de urgência, que podem obrigar o agressor (afastamento do lar, proibição de aproximação e contato, proibição de frequentar determinados lugares, suspensão de porte de armas) ou proteger a vítima (encaminhamento a programa de proteção, recondução ao domicílio após afastamento do agressor). O descumprimento de medida protetiva configura crime autônomo, com pena de detenção de 3 meses a 2 anos."
    ],
    "pontosChave": [
      "Cinco formas de violência: física, psicológica, sexual, patrimonial e moral — não se limita à agressão física.",
      "Lei se aplica em unidade doméstica, família e relação íntima de afeto, inclusive relações homoafetivas entre mulheres.",
      "Descumprimento de medida protetiva de urgência é crime autônomo (detenção de 3 meses a 2 anos)."
    ],
