    "corpo": [
      "A Lei de Crimes Hediondos traz um rol taxativo (numerus clausus) de crimes considerados hediondos — não cabe interpretação extensiva ou analógica para incluir crimes fora dessa lista, ainda que sejam igualmente graves. Entre os principais: homicídio qualificado, homicídio praticado por milícia privada ou grupo de extermínio (mesmo que na forma simples), lesão corporal seguida de morte quando praticada em contexto de violência doméstica ou por milícia/grupo de extermínio, latrocínio, extorsão qualificada pela morte, extorsão mediante sequestro, estupro e estupro de vulnerável, epidemia com resultado morte, e falsificação de produtos terapêuticos/medicinais.",
      "Além dos crimes hediondos propriamente ditos, a Constituição e a própria lei equiparam a eles, para efeitos de tratamento mais rigoroso, a prática de tortura, tráfico ilícito de entorpecentes e terrorismo — daí a expressão comum 'hediondos e equiparados'. Esses crimes são insuscetíveis de anistia, graça e indulto, e de fiança (esta última vedação está na própria Constituição, art. 5º, XLIII).",
      "Quanto à execução da pena, crimes hediondos e equiparados exigem frações mais rigorosas para progressão de regime do que crimes comuns: em regra, 40% da pena para réu primário e 60% para reincidente (havendo ainda frações intermediárias e mais gravosas para casos específicos, como resultado morte, que podem chegar a 50% e 70%, respectivamente) — essas frações foram alteradas pelo Pacote Anticrime (Lei 13.964/2019) e merecem conferência sempre atualizada, por ser ponto de frequente reforma legislativa."
    ],
