    "corpo": [
      "A Lei 12.850/2013 conceitua organização criminosa como a associação de 4 ou mais pessoas, estruturalmente ordenada e caracterizada pela divisão de tarefas, ainda que informalmente, com objetivo de obter, direta ou indiretamente, vantagem de qualquer natureza, mediante a prática de infrações penais cujas penas máximas sejam superiores a 4 anos, ou que sejam de caráter transnacional. Todos esses requisitos são cumulativos: falta um deles, não se configura organização criminosa nos termos da lei, ainda que exista algum tipo de associação entre pessoas.",
      "A lei prevê meios especiais de obtenção de prova, inexistentes ou pouco usados em investigações comuns: colaboração premiada (o colaborador, mediante acordo homologado judicialmente, fornece informações relevantes em troca de benefícios como redução de pena, perdão judicial ou substituição de pena privativa por restritiva), captação ambiental de sinais, ação controlada (retardamento da intervenção policial para obter mais elementos de prova), infiltração de agentes de polícia (autorizada judicialmente, por prazo determinado, com estrita observância de limites) e acesso a registros de ligações telefônicas e telemáticas.",
      "Participar de organização criminosa é crime autônomo (art. 2º), com pena de reclusão de 3 a 8 anos, além das penas correspondentes às demais infrações praticadas — a pena é aumentada em situações específicas, como se há emprego de arma de fogo, se há participação de criança/adolescente, se há concurso com funcionário público valendo-se da função, ou se o produto/proveito da infração se destina a país estrangeiro."
    ],
