    "title": "Estatuto da Criança e do Adolescente: ato infracional",
    "assunto": "ECA — ato infracional e medidas socioeducativas",
    "tecnica": "Reconhecimento do procedimento de apuração e das medidas cabíveis conforme a idade",
    "competencia": "Diferenciar criança de adolescente para fins de responsabilização e reconhecer as medidas socioeducativas",
    "dificuldade": "Média",
    "tempoLeituraMin": 8,
    "tempoExercicioMin": 6,
    "bancaRatings": {
      "FGV": 4,
      "CESPE": 5,
      "FCC": 4,
      "ENEM": 3
    },
    "termosChave": [
      "ato infracional",
      "medida socioeducativa",
      "internação"
    ],
    "corpo": [
      "O Estatuto da Criança e do Adolescente define criança como pessoa até 12 anos de idade incompletos, e adolescente como aquela entre 12 e 18 anos de idade. Ato infracional é a conduta descrita como crime ou contravenção penal, praticada por criança ou adolescente — mas as consequências jurídicas são radicalmente diferentes conforme a faixa etária: à criança que pratica ato infracional aplicam-se apenas medidas de proteção (nunca medida socioeducativa); ao adolescente, aplicam-se medidas socioeducativas.",
      "As medidas socioeducativas, em ordem crescente de gravidade, são: advertência, obrigação de reparar o dano, prestação de serviços à comunidade, liberdade assistida, inserção em regime de semiliberdade e internação em estabelecimento educacional. A internação é medida privativa de liberdade, sujeita aos princípios da brevidade, excepcionalidade e respeito à condição peculiar de pessoa em desenvolvimento — o prazo máximo de internação é de 3 anos, com reavaliação obrigatória a cada 6 meses.",
      "A apreensão do adolescente em flagrante de ato infracional exige comunicação imediata à autoridade judiciária e à família (ou pessoa indicada), e apresentação ao Ministério Público em até 24 horas. O adolescente apreendido tem direito a permanecer separado de adultos, à identificação regular do procedimento, e à entrevista pessoal com representante do Ministério Público — todo o procedimento se desenvolve sob a garantia de contraditório e ampla defesa, com participação obrigatória de defensor."
    ],
    "pontosChave": [
      "Criança (até 12 anos incompletos): apenas medida de proteção. Adolescente (12 a 18 anos): medida socioeducativa.",
      "Medidas socioeducativas em ordem crescente: advertência, reparação de dano, prestação de serviços, liberdade assistida, semiliberdade, internação.",
      "Internação: máximo 3 anos, reavaliação a cada 6 meses, respeitando brevidade e excepcionalidade."
    ],
    "checkRapido": {
      "pergunta": "Uma criança de 10 anos pratica uma conduta que, se fosse cometida por adulto, seria crime de furto. Qual medida pode ser aplicada a ela?",
      "opcoes": [
        "Medida socioeducativa de advertência",
        "Apenas medida de proteção, nunca medida socioeducativa",
        "Internação, dada a gravidade da conduta"
      ],
      "correta": 1,
      "justificativa": "Como a pessoa tem 10 anos, é considerada criança pelo ECA (até 12 anos incompletos) — a ela nunca se aplica medida socioeducativa, apenas medidas de proteção previstas no próprio Estatuto (encaminhamento à família, orientação, tratamento, entre outras), independentemente da gravidade da conduta praticada."
    },
    "oQueCobra": "Diferenciar criança de adolescente para fins de responsabilização, e reconhecer as medidas socioeducativas em sua ordem de gravidade.",
    "precisaSaberAntes": "Memorizar o marco etário exato (12 anos incompletos separa criança de adolescente) para aplicar corretamente as consequências.",
    "explicacao": [
      {
        "titulo": "Remissão — perdão ou exclusão do processo",
        "texto": "Remissão é um instituto que pode ser concedido pelo Ministério Público (antes de iniciado o procedimento, como forma de exclusão do processo) ou pela autoridade judiciária (como forma de suspensão ou extinção do processo já iniciado), considerando as circunstâncias e consequências do fato, o contexto social e a personalidade do adolescente — pode ou não ser cumulada com medida socioeducativa (exceto semiliberdade e internação)."
      },
      {
        "titulo": "Internação-sanção",
        "texto": "Diferente da internação como medida principal, existe a internação-sanção, aplicável por prazo máximo de 3 meses, quando o adolescente descumpre reiteradamente e injustificadamente medida socioeducativa anteriormente imposta — não se confunde com nova apuração de ato infracional, é consequência do descumprimento da medida."
      }
    ],
    "comoIdentificar": "Casos que descrevem a idade do autor do ato infracional testam se cabe medida de proteção (criança) ou socioeducativa (adolescente), e qual medida é proporcional.",
    "pegadinhas": [
      "Aplicar medida socioeducativa a criança, ignorando que a ela cabem apenas medidas de proteção.",
      "Não observar o prazo máximo de internação (3 anos) e a reavaliação obrigatória a cada 6 meses.",
      "Confundir remissão (perdão/exclusão) com absolvição — são institutos distintos, com fundamentos e efeitos próprios."
    ],
    "resumoFrase": "Até 12 anos incompletos, só medida de proteção; de 12 a 18, medida socioeducativa — internação é excepcional, breve, máximo 3 anos.",
